// The shell. One window, one board, Electron defaults with nothing loosened.
// contextIsolation + sandbox + no nodeIntegration. A renderer cannot name a
// path; every path comes from a dialog, argv, open-file, or the store.
// Two web contents: the window's own is the title bar (chrome/), and the board
// runs in a view below it. desktop/icons/ is generated by tools/gen-desktop-icons.mjs.

import { app, BrowserWindow, Menu, WebContentsView, dialog, ipcMain, screen, shell } from 'electron';
import type {
  BrowserWindowConstructorOptions, HandlerDetails, IpcMainEvent, IpcMainInvokeEvent,
  MessageBoxOptions, WebContents, WebPreferences, WindowOpenHandlerResponse,
} from 'electron';
import { join, dirname } from 'node:path';
import { existsSync, mkdirSync, readFileSync, writeFileSync, unlinkSync } from 'node:fs';
import { registerSchemes, serveWeb, APP_CHROME, APP_INDEX, APP_ORIGIN } from './protocol.ts';
import { initLog, log } from './log.ts';
import { buildMenu, menuModel, runMenuItem } from './menu.ts';
import type { MenuActions, ViewAction } from './menu.ts';
import type { Point, Subject, WinState } from './chrome/bridge.ts';
import * as store from './store.ts';
import * as files from './files.ts';
import * as boards from './boards.ts';
// Each loads its heavy binary on first use, not at startup.
import * as ffmpeg from './native/ffmpeg.ts';
import * as matte from './native/matte.ts';
import * as decode from './native/decode.ts';
import * as updates from './updates.ts';

const isMac = process.platform === 'darwin';

/** A quit is under way. holdCloseForFlush() stops the window's close for the
 * flush, and Electron takes a stopped close as a cancelled quit. Windows and
 * Linux quit anyway when the last window closes, and macOS does not, so the
 * flush asks again. Without it, Cmd+Q on a Mac closed the window and left the
 * app running, and the smoke test waited for an exit that never came. */
let quitting = false;

// Files the OS asked for before a window existed (macOS open-file can precede ready).
const pending: string[] = [];

// Read once at boot by the renderer; empty on ordinary runs.
let startupNote = '';

// The `portable` marker is beside the exe. updates.ts never runs an installer
// over a portable copy, which would put a second copy somewhere else.
let portableCopy = false;
// Whether userData really moved beside the exe. False on read-only media,
// where a portable copy falls back to the ordinary folder.
let portableData = false;

// Move userData beside the exe when the `portable` marker exists.
// Falls back on read-only media and toasts the actual path.
// Must run before `ready` (setPath is ignored after that).
function claimPortableData(): void {
  const beside = dirname(app.getPath('exe'));
  if (!existsSync(join(beside, 'portable'))) return;
  portableCopy = true;
  const data = join(beside, 'data');
  try {
    mkdirSync(data, { recursive: true });
    // Probe-write to confirm the medium is writable.
    const probe = join(data, '.writable');
    writeFileSync(probe, '');
    unlinkSync(probe);
    app.setPath('userData', data);
    portableData = true;
  } catch (err) {
    startupNote = 'This folder cannot be written to, so mbrd is keeping your '
      + 'boards in ' + app.getPath('userData') + ' for this run.';
    // log() has no file yet; initLog() runs after `ready`.
    console.warn('[mbrd] portable data folder refused:', err);
  }
}

/** electron-builder.yml's appId. The installer gives its shortcuts this as their
 *  AppUserModelID, and Windows groups a taskbar button with a shortcut, and
 *  takes its icon, only when the window says the same. tests/desktop-icon.test.js
 *  holds the two in step. */
const APP_ID = 'com.valjdakosta.mbrd';

function main(): void {
  claimPortableData();
  registerSchemes();
  if (process.platform === 'win32') app.setAppUserModelId(APP_ID);

  // preventDefault required or macOS treats it as unhandled.
  app.on('open-file', (event, path) => {
    event.preventDefault();
    handOver([path]);
  });

  // Windows/Linux: a second launch hands its argv over and quits.
  app.on('second-instance', (_event, argv) => {
    const win = current();
    if (win) {
      if (win.isMinimized()) win.restore();
      win.focus();
    }
    handOver(boardsIn(argv));
  });

  app.whenReady().then(async () => {
    initLog();
    // Unpackaged macOS only; a packaged copy reads the .icns from the bundle.
    if (isMac && !app.isPackaged) {
      app.dock?.setIcon(join(__dirname, '..', 'icons', 'icon.png'));
    }
    // Repeat the portable warning now that the log file exists.
    if (startupNote) log('warn', 'portable fallback', { note: startupNote });
    // In the data folder for a portable copy, and for a run given its own data
    // folder (the smoke test), so neither writes into Documents.
    const inData = portableData || app.commandLine.hasSwitch('user-data-dir');
    log('info', 'boards folder', { path: boards.chooseFolder(inData) });
    serveWeb();
    wireStore();
    wireFiles();
    wireApp();
    wireNative();
    wireChrome();
    // Never shown on Windows or Linux. It is what makes the accelerators live.
    Menu.setApplicationMenu(buildMenu(menuActions));
    // Vouch for shelf paths before the window asks whether they exist.
    await vouchShelf();
    // Not awaited: leftover .trash- directories are harmless.
    void store.sweepTrash();
    // First launch's own argv (double-click when app was not running).
    handOver(boardsIn(process.argv));
    createWindow();

    // macOS dock-click reopens the board window.
    app.on('activate', () => {
      if (!current()) createWindow();
    });
  }).catch(err => log('error', 'startup failed', err));

  // On macOS the process stays alive with no windows.
  app.on('window-all-closed', () => {
    log('info', 'every window closed', { quitting });
    if (!isMac) app.quit();
  });
  app.on('before-quit', () => {
    log('info', 'quit asked');
    quitting = true;
  });
  app.on('will-quit', () => log('info', 'quitting'));
}

// .ico on Windows (multi-size); .png elsewhere. __dirname is dist/.
function iconPath(): string {
  const file = process.platform === 'win32' ? 'icon.ico' : 'icon.png';
  return join(__dirname, '..', 'icons', file);
}

/** The same locks on every web contents here. Only the preload differs. */
function locked(preload: string): WebPreferences {
  return { contextIsolation: true, sandbox: true, nodeIntegration: false, preload };
}

// ---------------------------------------------------------------------------
// The window: two web contents
//
// The window's own contents is the title bar page (chrome/titlebar.html), and
// the board runs in a WebContentsView parked below it. So the board's viewport
// starts under the bar for real, and no rule in the page has to make room for
// it. The bar is the window's own contents, and not a second view, because on
// Windows the OS reads the drag region from the window's own contents.
// ---------------------------------------------------------------------------

/** A starting value only. The bar measures --tb-h in titlebar.css and reports it. */
const TB_H_DEFAULT = 32;

let mainWindow: BrowserWindow | null = null;
let boardView: WebContentsView | null = null;
/** What the bar last showed, sent again when the bar reloads or loads late. */
let lastSubject: Subject = { title: '', dirty: false };
/** Whether the board view shows the board. It shows /patch in its place too. */
let boardShown = true;
/** What the board last reported, shown again when it comes back from /patch. */
let lastDocument: unknown = null;
/** Set by createWindow. The IPC below lives at module scope, so `activate`
 * making a second window cannot stack a second set of listeners. */
let chromeHooks: { pushState(): void, layout(): void } | null = null;

// The board window. Not the menu panel.
const current = (): BrowserWindow | null =>
  mainWindow && !mainWindow.isDestroyed() ? mainWindow : null;

/** The board's web contents. Everything that talks to the page talks to this:
 * current().webContents is the title bar. */
const appContents = (): WebContents | null =>
  boardView && !boardView.webContents.isDestroyed() ? boardView.webContents : null;

/** Give the keys back to the board after the bar or a menu took them. */
const focusBoard = () => appContents()?.focus();

// ---------------------------------------------------------------------------
// Window size and place, in userData/window-state.json, so a portable copy
// keeps them beside the exe with everything else.
// ---------------------------------------------------------------------------

interface WindowState {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  maximized: boolean;
}

const stateFile = () => join(app.getPath('userData'), 'window-state.json');

function readState(): WindowState {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(stateFile(), 'utf8'));
  } catch {
    // No file on a first run, or a torn one: the defaults.
    return { maximized: false };
  }
  if (!parsed || typeof parsed !== 'object') return { maximized: false };
  // SAFETY: a non-null object, and every field is typed unknown and checked below.
  const saved = parsed as {
    x?: unknown, y?: unknown, width?: unknown, height?: unknown, maximized?: unknown,
  };
  const int = (n: unknown): number | undefined =>
    typeof n === 'number' && Number.isInteger(n) ? n : undefined;
  const state: WindowState = {
    width: int(saved.width),
    height: int(saved.height),
    maximized: saved.maximized === true,
  };
  // Only a place a screen still shows. A monitor unplugged since the last run
  // would put the window where nobody can reach it.
  const x = int(saved.x);
  const y = int(saved.y);
  if (x !== undefined && y !== undefined && onScreen(x, y)) {
    state.x = x;
    state.y = y;
  }
  return state;
}

/** Whether a window placed at x, y has its bar's left end on some screen. */
function onScreen(x: number, y: number): boolean {
  return screen.getAllDisplays().some(({ workArea: a }) =>
    x + 40 >= a.x && x + 40 < a.x + a.width && y + 10 >= a.y && y + 10 < a.y + a.height);
}

/** The normal bounds whatever the state, so a window closed maximised or in
 * full screen comes back to its own size when it is restored. */
function writeState(win: BrowserWindow): void {
  if (win.isDestroyed()) return;
  try {
    mkdirSync(dirname(stateFile()), { recursive: true });
    writeFileSync(stateFile(), JSON.stringify({ ...win.getNormalBounds(), maximized: win.isMaximized() }));
  } catch (err) {
    log('warn', 'could not keep the window size and place', { err: String(err) });
  }
}

function createWindow(): BrowserWindow {
  const saved = readState();
  const options: BrowserWindowConstructorOptions = {
    width: saved.width ?? 1280,
    height: saved.height ?? 840,
    // Undefined centres the window.
    x: saved.x,
    y: saved.y,
    minWidth: 480,
    minHeight: 400,
    // Black avoids a white flash before the board paints.
    backgroundColor: '#000000',
    show: false,
    // The bar is drawn by this window's own contents, so the OS frame goes.
    // macOS keeps its frame for the traffic lights and hides only the bar.
    // autoHideMenuBar: the menus are drawn, and the hidden Menu is there only
    // for its accelerators.
    frame: isMac,
    autoHideMenuBar: true,
    // The bar's own preload. It moves the window and draws the menus, and has
    // no business reaching the store, the files or ffmpeg.
    webPreferences: locked(join(__dirname, 'chrome', 'preload.js')),
  };

  if (isMac) {
    options.titleBarStyle = 'hidden';
    // Centred in the 32px bar (--tb-h in chrome/titlebar.css).
    options.trafficLightPosition = { x: 18, y: 10 };
  } else {
    // Taskbar/Alt-Tab. macOS reads the bundle icon instead.
    options.icon = iconPath();
  }

  const win = new BrowserWindow(options);
  mainWindow = win;
  guardChrome(win.webContents);

  // The board, with the board's preload.
  const view = new WebContentsView({ webPreferences: locked(join(__dirname, 'preload.js')) });
  view.setBackgroundColor('#000000');
  win.contentView.addChildView(view);
  boardView = view;
  boardShown = true;
  lastDocument = null;
  guardBoard(view.webContents);

  // The view shows /patch in the board's place, under the same bar. The bar
  // and the window title follow the page it shows.
  view.webContents.on('did-navigate', (_event, url) => {
    boardShown = isBoardUrl(url);
    if (boardShown && lastDocument) showDocument(lastDocument);
  });
  view.webContents.on('page-title-updated', (_event, title) => {
    if (!boardShown) showPage(title);
  });

  /* Full screen is tracked from the events, not read back from the window.
     Electron on Windows fires these before isFullScreen() returns the new value,
     and FileAnalyser's bar hid itself in a normal window that way. Registered
     first, so every listener below reads the new value. */
  let fullScreen = win.isFullScreen();
  win.on('enter-full-screen', () => { fullScreen = true; });
  win.on('leave-full-screen', () => { fullScreen = false; });

  // The board under the bar, or over the whole window in full screen, where
  // the bar hides. A child view has no layout of its own, so every geometry
  // change runs this.
  const layout = () => {
    if (win.isDestroyed()) return;
    const { width, height } = win.getContentBounds();
    const top = fullScreen ? 0 : tbHeight;
    view.setBounds({ x: 0, y: top, width, height: Math.max(0, height - top) });
  };
  win.on('resize', layout);
  win.on('maximize', layout);
  win.on('unmaximize', layout);
  win.on('enter-full-screen', layout);
  win.on('leave-full-screen', layout);

  // An open menu is a window pinned to a point on this one, so it cannot
  // follow it. Native menus close on the same events.
  win.on('move', closePanel);
  win.on('resize', closePanel);
  win.on('minimize', closePanel);
  win.on('maximize', closePanel);
  win.on('unmaximize', closePanel);
  win.on('enter-full-screen', closePanel);
  win.on('leave-full-screen', closePanel);

  // The bar draws the maximise glyph and recedes out of focus, so it hears
  // every change, the ones it did not cause too: Win+Up, Snap, leaving full screen.
  const pushState = () => {
    if (win.isDestroyed()) return;
    const state: WinState = {
      maximized: win.isMaximized(),
      fullScreen,
      // An open menu is a window of its own and takes the focus. Without this
      // the bar would recede exactly while it is in use.
      focused: win.isFocused() || panelFocused(),
    };
    win.webContents.send('chrome:state', state);
  };
  win.on('maximize', pushState);
  win.on('unmaximize', pushState);
  win.on('enter-full-screen', pushState);
  win.on('leave-full-screen', pushState);
  win.on('focus', pushState);
  win.on('blur', pushState);

  // Written 400 ms after the last move or resize, and again on close.
  let saveTimer: ReturnType<typeof setTimeout> | undefined;
  const queueSave = () => {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => writeState(win), 400);
  };
  win.on('resize', queueSave);
  win.on('move', queueSave);
  win.on('close', () => writeState(win));

  // maximize() shows a hidden window by itself, so it waits for the reveal too.
  const reveal = () => {
    if (saved.maximized && !win.isMaximized()) win.maximize();
    win.show();
  };

  // Show on the board's first paint, not the bar's: the bar is ready at once,
  // and showing then would flash an empty window for as long as the board takes.
  view.webContents.once('did-finish-load', () => {
    layout();
    reveal();
    // Built now, hidden, so the first menu opens as fast as every other.
    ensurePanelWindow();
    // Deliver any files the OS handed over before the window existed.
    void deliver();
    // After paint, not before: show the board first.
    updates.startUpdates({
      window: current,
      portable: portableCopy,
      // The title bar's Update button.
      announce: offer => current()?.webContents.send('chrome:update', offer),
    });
  });

  holdCloseForFlush(win, view.webContents);
  win.on('closed', () => {
    // The hidden panel is a window too, and would keep window-all-closed from firing.
    if (panelWin && !panelWin.isDestroyed()) panelWin.destroy();
    if (mainWindow !== win) return;
    mainWindow = null;
    boardView = null;
    chromeHooks = null;
  });

  chromeHooks = { pushState, layout };
  layout();
  win.loadURL(APP_CHROME + 'titlebar.html').catch(err => log('error', 'could not load the title bar', err));
  view.webContents.loadURL(APP_INDEX).catch(err => log('error', 'could not load the app', err));
  // A load that never finishes must not leave an invisible window behind.
  setTimeout(() => {
    if (!win.isDestroyed() && !win.isVisible()) reveal();
  }, 4000);
  return win;
}

/** Only http(s) to the system browser; all other schemes refused. */
function openOutside({ url }: HandlerDetails): WindowOpenHandlerResponse {
  if (/^https?:$/.test(safeProtocol(url))) {
    shell.openExternal(url).catch(err => log('warn', 'could not open a link', { url, err: String(err) }));
  } else {
    log('warn', 'refused to open a link', { url });
  }
  return { action: 'deny' };
}

/** Renderer errors and warnings into the log (CSP violations arrive here). */
function logConsole(wc: WebContents, who: string): void {
  wc.on('console-message', event => {
    if (event.level !== 'error' && event.level !== 'warning') return;
    log(event.level === 'error' ? 'error' : 'warn', `${who}: ${event.message}`,
      { source: event.sourceId, line: event.lineNumber });
  });
}

/** The board's contents. The rules the window's contents had before the split. */
function guardBoard(wc: WebContents): void {
  wc.setWindowOpenHandler(openOutside);

  // The board leaves only for a page of its own site, /patch in practice, and
  // comes back by "Back to the board" (href="/"). main loads each page itself,
  // which fires no will-navigate. Leaving the board flushes it first, as a
  // close does: the desktop page saves when main asks, not on pagehide.
  wc.on('will-navigate', (event, url) => {
    event.preventDefault();
    if (!url.startsWith(APP_ORIGIN + '/')) {
      log('warn', 'refused a navigation', { url });
      return;
    }
    // One address for the board, the one the smoke test and the page expect.
    const target = isBoardUrl(url) ? APP_INDEX + url.slice(url.search(/[?#]|$/)) : url;
    const go = () => {
      if (wc.isDestroyed()) return;
      wc.loadURL(target).catch(err => log('error', 'could not load a page', { url: target, err: String(err) }));
    };
    if (boardShown) void flushBoard(wc).then(go);
    else go();
  });

  // Ctrl+R before the page sees the key, so no handler in the page can take
  // it. The preventDefault also stops the menu's own CmdOrCtrl+R, so it reloads
  // once. Not on macOS, where the system menu delivers it.
  if (!isMac) {
    wc.on('before-input-event', (event, input) => {
      const reload = input.key.toLowerCase() === 'r' && (input.control || input.meta);
      if (input.type !== 'keyDown' || !reload || input.alt || input.shift) return;
      event.preventDefault();
      wc.reload();
    });
  }

  // No webviews in this app.
  wc.on('will-attach-webview', event => {
    event.preventDefault();
    log('warn', 'refused a webview');
  });

  logConsole(wc, 'renderer');
}

/** The bar's and the menu panel's contents. Neither navigates or opens anything. */
function guardChrome(wc: WebContents): void {
  wc.setWindowOpenHandler(({ url }) => {
    log('warn', 'refused a window from the title bar', { url });
    return { action: 'deny' };
  });
  wc.on('will-navigate', (event, url) => {
    event.preventDefault();
    log('warn', 'refused a navigation from the title bar', { url });
  });
  wc.on('will-attach-webview', event => event.preventDefault());
  logConsole(wc, 'title bar');
}

/** The board page: index.html, or the bare root it is also served at. */
function isBoardUrl(url: string): boolean {
  if (!url.startsWith(APP_ORIGIN + '/')) return false;
  const path = url.slice(APP_ORIGIN.length).split(/[?#]/)[0];
  return path === '/' || path === '/index.html';
}

/** Ask the board to save, and wait for its answer, 10 s at most. The page
 * answers on its own channel, and one that never answers must not hold a
 * close or a navigation for good. */
function flushBoard(board: WebContents): Promise<void> {
  return new Promise(resolve => {
    const done = () => {
      clearTimeout(timer);
      ipcMain.removeListener('app:close-now', onFlushed);
      resolve();
    };
    const onFlushed = (event: IpcMainEvent) => {
      if (event.sender === board) done();
    };
    const timer = setTimeout(() => {
      log('warn', 'the page did not finish flushing in 10s; going on anyway');
      done();
    }, 10_000);
    ipcMain.on('app:close-now', onFlushed);
    board.send('app:close-requested');
  });
}

// Hold close until the board finishes flushing. The window closes, and the
// board is the one with something to flush.
function holdCloseForFlush(win: BrowserWindow, board: WebContents): void {
  let flushed = false;
  let flushing = false;
  win.on('close', event => {
    // Nothing to flush: the board is gone, or /patch is in its place, which
    // saved it on the way out and has no page script to answer.
    if (flushed || board.isDestroyed() || !boardShown) return;
    event.preventDefault();
    if (flushing) return;
    flushing = true;
    log('info', 'close held for the flush', { quitting });
    closePanel();
    void flushBoard(board).then(() => {
      flushed = true;
      log('info', 'flushed, closing', { quitting });
      // close() not destroy(): the handler stands aside once flushed is set.
      if (!win.isDestroyed()) win.close();
      // The hold cancelled the quit, so ask again (see `quitting`).
      if (quitting) app.quit();
    });
  });
}

/** Jobs waiting for the board to load again, or null when none is loading. */
let returning: (() => void)[] | null = null;

/** Bring the board back in place of /patch, then run `then`. A load already
 * under way takes the new job too. */
function backToBoard(then: () => void): void {
  const wc = appContents();
  if (!wc) return;
  if (returning) {
    returning.push(then);
    return;
  }
  const jobs = [then];
  returning = jobs;
  const loaded = () => {
    returning = null;
    for (const job of jobs) job();
  };
  wc.once('did-finish-load', loaded);
  wc.loadURL(APP_INDEX).catch(err => {
    wc.removeListener('did-finish-load', loaded);
    returning = null;
    log('error', 'could not load the app', err);
  });
}

/** A menu row that acts on the board. With /patch in the board's place the
 * board comes back first, and the page waits for its start-up before it runs
 * the command. What Changed there is already answered. */
function runOnBoard(cmd: string): void {
  if (boardShown) {
    appContents()?.send('app:command', cmd);
    return;
  }
  if (cmd === 'patchNotes') return;
  backToBoard(() => appContents()?.send('app:command', cmd));
}

/** The window title and the bar's subject for a page in the board's place:
 * its own <title>, less the " - mbrd" every page of the site ends with. */
function showPage(title: string): void {
  const win = current();
  if (!win) return;
  const name = title.replace(/ - mbrd$/, '') || 'mbrd';
  win.setTitle(`${name} — mbrd`);
  lastSubject = { title: name, dirty: false };
  win.webContents.send('chrome:subject', lastSubject);
  if (!isMac) return;
  win.setRepresentedFilename('');
  win.setDocumentEdited(false);
}

function safeProtocol(url: string): string {
  try {
    return new URL(url).protocol;
  } catch {
    return '';
  }
}

// ---------------------------------------------------------------------------
// The menu's actions
// ---------------------------------------------------------------------------

const menuActions: MenuActions = {
  send: runOnBoard,
  view: viewAction,
  showData,
  // updates.ts answers in its own dialogs.
  checkUpdates: () => { void updates.checkForUpdates(); },
};

/* The bar, the panel and the board share one origin, and Chromium keeps the
   zoom level per origin, so zooming the board zooms the bar with it. The bar
   reports its height in its own CSS pixels, and bounds are window pixels, so
   main scales every number it gets from a chrome page. The factor is 1.2^level
   from the level just set: read back from the bar, it lands a step behind. */
let zoomFactor = 1;
/** What the bar last reported, in its own pixels. */
let tbCssHeight = TB_H_DEFAULT;
/** Where the board starts, in window pixels. */
let tbHeight = TB_H_DEFAULT;

function applyBarHeight(): void {
  // Ceil, not round: rounding down parks the board a fraction of a pixel over
  // the bar, which covers the bar's bottom hairline.
  const h = Math.max(1, Math.ceil(tbCssHeight * zoomFactor));
  if (h === tbHeight) return;
  tbHeight = h;
  chromeHooks?.layout();
}

/** The rows that were roles, run against the board's view. */
function viewAction(what: ViewAction): void {
  const win = current();
  const wc = appContents();
  if (!win || !wc) return;
  const setZoom = (level: number) => {
    wc.setZoomLevel(level);
    zoomFactor = 1.2 ** level;
    applyBarHeight();
  };
  switch (what) {
    case 'reload': wc.reload(); break;
    case 'devTools': wc.toggleDevTools(); break;
    // Half a level a step, as Electron's zoom roles take it, between
    // FileAnalyser's limits.
    case 'zoomIn': setZoom(Math.min(9, wc.getZoomLevel() + 0.5)); break;
    case 'zoomOut': setZoom(Math.max(-8, wc.getZoomLevel() - 0.5)); break;
    case 'zoomReset': setZoom(0); break;
    case 'fullScreen': win.setFullScreen(!win.isFullScreen()); break;
    // close() not destroy(), so holdCloseForFlush still applies.
    case 'close': win.close(); break;
  }
}

/** Help > Where My Data Is Stored. A portable copy promises to leave the
 * computer as it found it, and this makes that checkable. */
function showData(): void {
  const dir = app.getPath('userData');
  const options: MessageBoxOptions = {
    type: 'info',
    title: 'mbrd',
    message: portableData ? 'Portable copy' : 'Installed copy',
    detail: 'Your boards are .mbrd files. The ones mbrd makes are in '
      + boards.folder() + '. This folder keeps the recovery store, the list of '
      + 'boards and the logs.\n\n' + dir,
    buttons: ['Close', 'Open the folder'],
    defaultId: 0,
    cancelId: 0,
  };
  const win = current();
  const asked = win ? dialog.showMessageBox(win, options) : dialog.showMessageBox(options);
  asked.then(answer => {
    if (answer.response === 1) void shell.openPath(dir);
  }).catch(err => log('warn', 'the data dialog failed', { err: String(err) }));
}

// ---------------------------------------------------------------------------
// The title bar and the menu panel (chrome/)
//
// Every message checks its sender. The board is a separate web contents and
// has no business moving the window or opening a menu, and the bar has none
// reaching the store.
// ---------------------------------------------------------------------------

type Sender = IpcMainEvent | IpcMainInvokeEvent;
const fromChrome = (event: Sender) => event.sender === current()?.webContents;

/* Each open menu is a small window of its own. It cannot be drawn in the bar's
   page: the board is a child view, a child view composites above the contents
   it was added to, and so a panel dropped below the bar would sit under the
   board and never show. One window, reused: moved and refilled as the pointer
   slides along the menu titles. */
let panelWin: BrowserWindow | null = null;
let panelMenuId = '';
/* A click on the open menu's own title must close it. The click blurs the panel
   first, which closes it, and then the title asks to open it again. So a re-open
   of the menu that just closed is dropped for a moment. */
let panelClosedId = '';
let panelClosedAt = 0;

const fromPanel = (event: Sender) =>
  !!panelWin && !panelWin.isDestroyed() && event.sender === panelWin.webContents;
const panelFocused = () => !!panelWin && !panelWin.isDestroyed() && panelWin.isFocused();

function closePanel(): void {
  if (panelMenuId) {
    panelClosedId = panelMenuId;
    panelClosedAt = Date.now();
  }
  panelMenuId = '';
  if (panelWin && !panelWin.isDestroyed() && panelWin.isVisible()) panelWin.hide();
  current()?.webContents.send('chrome:menu-closed');
}

function ensurePanelWindow(): BrowserWindow | null {
  const parent = current();
  if (!parent) return null;
  if (panelWin && !panelWin.isDestroyed()) return panelWin;
  const win = new BrowserWindow({
    // Keeps it above the window it belongs to.
    parent,
    show: false,
    frame: false,
    resizable: false,
    movable: false,
    minimizable: false,
    maximizable: false,
    fullscreenable: false,
    skipTaskbar: true,
    backgroundColor: '#00000000',
    width: 220,
    height: 100,
    webPreferences: locked(join(__dirname, 'chrome', 'preload.js')),
  });
  panelWin = win;
  guardChrome(win.webContents);
  // No accelerators while a menu is open, as with a native one.
  if (!isMac) win.setMenu(null);
  // A click anywhere else, the bar, the board or another app, closes it.
  win.on('blur', () => {
    closePanel();
    chromeHooks?.pushState();
  });
  win.on('closed', () => {
    if (panelWin !== win) return;
    panelWin = null;
    panelMenuId = '';
  });
  win.loadURL(APP_CHROME + 'panel.html').catch(err => log('error', 'could not load the menu panel', err));
  return win;
}

function wireChrome(): void {
  ipcMain.handle('chrome:win', (event, action: unknown) => {
    const win = current();
    if (!win || !fromChrome(event)) return;
    if (action === 'minimize') {
      win.minimize();
    } else if (action === 'maximize') {
      if (win.isMaximized()) win.unmaximize();
      else win.maximize();
      focusBoard();
    } else if (action === 'close') {
      // close() not destroy(), so holdCloseForFlush still applies.
      win.close();
    }
  });

  // The menu as data. The bar draws it, and a click comes back as an id.
  ipcMain.handle('chrome:menu-model', event => (fromChrome(event) ? menuModel() : []));

  // The title's box arrives in the bar's own coordinates. Only main knows
  // where the window is, so the panel is placed when it reports its size.
  ipcMain.on('chrome:menu-open', (event, req: { id?: unknown, x?: unknown, y?: unknown } | null) => {
    if (!fromChrome(event)) return;
    const id = String(req?.id ?? '');
    const menu = menuModel().find(m => m.id === id);
    if (!menu) return;
    if (id === panelClosedId && Date.now() - panelClosedAt < 250) {
      panelClosedId = '';
      // The bar lit the title again on this click. It goes dark with the menu.
      event.sender.send('chrome:menu-closed');
      return;
    }
    const panel = ensurePanelWindow();
    if (!panel) return;
    panelMenuId = id;
    const at: Point = { x: Math.round(Number(req?.x) || 0), y: Math.round(Number(req?.y) || 0) };
    const send = () => {
      if (!panel.isDestroyed()) panel.webContents.send('panel:menu', { menu, at });
    };
    if (panel.webContents.isLoading()) panel.webContents.once('did-finish-load', send);
    else send();
  });

  ipcMain.on('chrome:menu-close', event => {
    if (!fromChrome(event)) return;
    closePanel();
    focusBoard();
  });

  // The bar's height from --tb-h, measured, so the number is written once.
  // Arrives on load and again on a resize or a font change. Zero in full
  // screen, where the bar hides, and ignored then.
  ipcMain.on('chrome:height', (event, px: unknown) => {
    if (!fromChrome(event)) return;
    const h = Math.round(Number(px) || 0);
    if (h <= 0) return;
    tbCssHeight = h;
    applyBarHeight();
  });

  // The bar loads before the board and asks, rather than being sent a state
  // before it can listen.
  ipcMain.on('chrome:ready', event => {
    if (!fromChrome(event)) return;
    chromeHooks?.pushState();
    event.sender.send('chrome:subject', lastSubject);
    event.sender.send('chrome:update', updates.currentOffer());
  });

  // The Update button. updates.ts quits for the install, and the quit writes
  // the board to its file first.
  ipcMain.on('chrome:update-press', event => {
    if (!fromChrome(event)) return;
    updates.clickUpdate();
  });

  // The panel has drawn itself and says how big it is. Only now is it placed
  // and shown, so it never flashes at the wrong size or place.
  ipcMain.on('panel:size', (event, size: { w?: unknown, h?: unknown, at?: { x?: unknown, y?: unknown } } | null) => {
    const parent = current();
    const panel = panelWin;
    if (!fromPanel(event) || !panelMenuId || !parent || !panel) return;
    // The size is in the panel's CSS pixels and the point in the bar's, and
    // bounds are window pixels. One origin, so one factor scales both.
    const w = Math.max(80, Math.ceil((Number(size?.w) || 0) * zoomFactor));
    const h = Math.max(24, Math.ceil((Number(size?.h) || 0) * zoomFactor));
    const at = { x: Number(size?.at?.x) || 0, y: Number(size?.at?.y) || 0 };
    const content = parent.getContentBounds();
    const area = screen.getDisplayMatching(content).workArea;
    // Clamped to the display: a panel is a window, and its parent does not keep it whole.
    const x = Math.min(Math.max(area.x, content.x + at.x * zoomFactor), area.x + area.width - w);
    const y = Math.min(Math.max(area.y, content.y + at.y * zoomFactor), area.y + area.height - h);
    panel.setBounds({ x: Math.round(x), y: Math.round(y), width: w, height: h });
    if (!panel.isVisible()) panel.show();
    chromeHooks?.pushState();
  });

  ipcMain.on('panel:run', (event, id: unknown) => {
    if (!fromPanel(event)) return;
    closePanel();
    focusBoard();
    // Looked up in the table, not trusted: the id comes from a renderer.
    runMenuItem(String(id ?? ''), menuActions);
  });

  ipcMain.on('panel:close', event => {
    if (!fromPanel(event)) return;
    closePanel();
    focusBoard();
  });
}

// ---------------------------------------------------------------------------
// Open-with
// ---------------------------------------------------------------------------

// Filter argv to .mbrd files only (ignore flags and the executable).
function boardsIn(argv: readonly string[]): string[] {
  return argv.filter(arg => /\.mbrd$/i.test(arg) && !arg.startsWith('-'));
}

// Queue paths and deliver once a window exists.
function handOver(paths: string[]): void {
  if (!paths.length) return;
  pending.push(...paths);
  void deliver();
}

async function deliver(): Promise<void> {
  const board = appContents();
  if (!board || !pending.length) return;
  // /patch in the board's place: the board comes back first. The page waits
  // for its own start-up before it opens anything.
  if (!boardShown) {
    backToBoard(() => void deliver());
    return;
  }
  const paths = pending.splice(0, pending.length);
  try {
    const handed = await Promise.all(paths.map(p => files.read(vouched(p))));
    board.send('app:open-files', handed);
    log('info', 'handed over', { paths });
  } catch (err) {
    log('error', 'could not open a file the OS handed over', { paths, err: String(err) });
  }
}

// OS-provided paths are as trusted as dialog results.
function vouched(path: string): string {
  files.vouch(path);
  return path;
}

// ---------------------------------------------------------------------------
// The bridge's other half
// ---------------------------------------------------------------------------

// Validation lives in the modules (store.ts, files.ts), not here.
function wireStore(): void {
  ipcMain.handle('store:get', (_e, s: string, k: string) => store.get(s, k));
  ipcMain.handle('store:set', (_e, s: string, k: string, v: unknown) => store.set(s, k, v));
  ipcMain.handle('store:del', (_e, s: string, k: string) => store.del(s, k));
  ipcMain.handle('store:keys', (_e, s: string) => store.keys(s));
  ipcMain.handle('store:clear', (_e, s: string) => store.clear(s));
  ipcMain.handle('store:getMany', (_e, s: string, ks: unknown[]) => store.getMany(s, ks));
  ipcMain.handle('store:setMany', (_e, s: string, es: [unknown, unknown][]) => store.setMany(s, es));
  ipcMain.handle('store:delMany', (_e, s: string, ks: unknown[]) => store.delMany(s, ks));
}

function wireFiles(): void {
  ipcMain.handle('files:pickOpen', () => files.pickOpen(current(), boards.folder()));
  ipcMain.handle('files:pickSave', (_e, suggested: unknown) =>
    files.pickSave(current(), suggested, boards.folder()));
  ipcMain.handle('files:pickImport', () => files.pickImport(current()));
  ipcMain.handle('files:write', (_e, path: unknown, data: unknown) => files.write(path, data));
  ipcMain.handle('files:append', (_e, path: unknown, data: unknown, at: unknown) => files.append(path, data, at));
  ipcMain.handle('files:read', (_e, path: unknown) => files.read(path));
  ipcMain.handle('files:exists', (_e, path: unknown) => files.exists(path));
  ipcMain.handle('boards:list', () => boards.list());
  ipcMain.handle('boards:create', (_e, suggested: unknown, data: unknown) => boards.create(suggested, data));
  ipcMain.handle('boards:rename', (_e, path: unknown, suggested: unknown) => boards.rename(path, suggested));
  ipcMain.handle('boards:trash', (_e, path: unknown) => boards.trash(path));
  ipcMain.handle('boards:reveal', () => boards.reveal());
}

function wireApp(): void {
  // clearAllData() asks for a fresh start; here that means a new process.
  ipcMain.on('app:relaunch', () => {
    log('info', 'relaunching');
    app.relaunch();
    app.exit(0);
  });

  // Window title, the bar's subject, the macOS proxy icon and the dirty dot.
  ipcMain.on('app:document', (event, state: unknown) => {
    if (event.sender === appContents()) showDocument(state);
  });

  // Startup messages (e.g. portable fallback), read once at boot.
  ipcMain.handle('app:startupNotes', () => startupNote);

  // The shell answers in its own dialogs, so the page gets nothing back.
  ipcMain.handle('updates:check', () => { void updates.checkForUpdates(); });
}

// Each handler returns null when unavailable; the renderer falls through.
function wireNative(): void {
  ipcMain.handle('native:can', () => ({
    transcode: ffmpeg.available(),
    matte: matte.available(),
  }));
  ipcMain.handle('native:firstFrame', (_e, bytes: unknown) =>
    bytes instanceof ArrayBuffer ? ffmpeg.firstFrame(bytes) : null);
  ipcMain.handle('native:transcode', (_e, bytes: unknown, opts: unknown) => {
    if (!(bytes instanceof ArrayBuffer)) return null;
    // ffmpeg.ts clamps both fields before they reach a command line.
    // SAFETY: transcode() passes each field through Math.round() and Math.max(),
    // so page input reaches the arguments only as a number (NaN at worst).
    return ffmpeg.transcode(bytes, (opts ?? {}) as ffmpeg.TranscodeOpts);
  });
  ipcMain.handle('native:matte', (_e, input: unknown) =>
    input instanceof Float32Array ? matte.matte(input) : null);
  ipcMain.handle('native:decode', (_e, bytes: unknown, name: unknown) =>
    bytes instanceof ArrayBuffer && typeof name === 'string' ? decode.decode(bytes, name) : null);
}

function showDocument(state: unknown): void {
  const win = current();
  if (!win || !state || typeof state !== 'object') return;
  lastDocument = state;
  // SAFETY: a non-null object, and every field is typed unknown and checked below.
  const { title, name, path, dirty } = state as {
    title?: unknown, name?: unknown, path?: unknown, dirty?: unknown,
  };

  const file = typeof name === 'string' ? name : '';
  const board = typeof title === 'string' && title ? title : 'Untitled board';
  // The star most programs put before an unsaved document's name.
  const mark = dirty === true ? '* ' : '';
  win.setTitle(mark + (file ? `${file} — ${board}` : board) + ' — mbrd');

  // The bar names the board and marks unsaved work.
  lastSubject = { title: board, dirty: dirty === true };
  win.webContents.send('chrome:subject', lastSubject);

  if (!isMac) return;
  // macOS proxy icon and document-edited dot.
  win.setRepresentedFilename(typeof path === 'string' ? path : '');
  win.setDocumentEdited(dirty === true);
}

// Vouch for paths from the shelf index (they outlive the process that made them).
async function vouchShelf(): Promise<void> {
  try {
    const index = await store.get('kv', 'library-index');
    if (!Array.isArray(index)) return;
    let n = 0;
    for (const row of index) {
      if (row && typeof row === 'object' && 'path' in row) {
        // SAFETY: an object with a path key, and vouch() keeps only a non-empty string.
        files.vouch((row as { path?: unknown }).path);
        n++;
      }
    }
    if (n) log('info', 'shelf file rows vouched for', { n });
  } catch (err) {
    log('warn', 'could not read the shelf index', err);
  }
}

// Two copies would be two writers over one recovery store. Last in the file,
// so every declaration above is set before main() runs.
if (!app.requestSingleInstanceLock()) {
  app.quit();
} else {
  main();
}
